/* Lycée de Bahouan - Bulletin de notes annuel (modèle validé : reproduction du bulletin officiel).
   Remplit tout seul depuis la base : identité de l'élève, matières de sa série et coefficients, notes par séquence (Éval.1 à 6),
   moyennes, rangs, appréciations (L.mention), conduite (absences) et profil de la classe.
   Réglages (professeurs, seuils, signature) : bloc « bulletin » de config.js. */
(function(){
const H = window.Honneur, S = window.SITE || {}, esc = window.esc || (s => String(s == null ? '' : s)), L = window.L;
if (!H || !L) return;
const CFG = Object.assign({
  section: 'FRANCOPHONE',
  specialites: { C: 'Mathématiques', D: 'SVTEEHB', AE: 'Espagnol', AD: 'Allemand' },   /* matière de spécialité selon la série */
  profs: {},                 /* secours si la base n'a pas le professeur : { "Mathématiques": "M. DJOFACK" } */
  profPrincipal: '',         /* signature écrite du professeur principal (texte) */
  seuilsCompetences: [7.5, 10, 14],   /* < 7,5 Non acquises · < 10 A acquérir · < 14 En cours d'acquisition · sinon Acquises */
  decision: { passe: 12, conditionnel: 10 }   /* ≥ 12 passe · ≥ 10 « Redouble si échec » · sinon redouble */
}, S.bulletin || {});
const LOGO = 'data:image/png;base64,';

/* matières : [clé en base, libellé du bulletin, groupe 0 littéraire / 1 scientifique / 2 complémentaire] */
const TAB = [['Langue','Langue Française',0],['Anglais','Anglais',0],['Histoire/Géographie','Histoire/Geographie',0],['Philosophie','Philosophie',0],['Littérature','Littérature',0],
  ['ECM','Education à la citoyenneté',0],['Education à la citoyenneté','Education à la citoyenneté',0],['Informatiques','Informatique Fondamentale',0],['Espagnol','Espagnol',0],['Allemand','Allemand',0],
  ['Mathématiques','Mathématiques',1],['SVT','SVTEEHB',1],['Chimie','Chimie',1],['Physiques','Physique',1],
  ['EPS','Education Physique & Sportive',2],['Education Physique & Sportive','Education Physique & Sportive',2],['Dessin','Dessin',2],['TM','Travail Manuel',2]];
const GR = [{ t: 'Matières Littéraires', s: 'Sous total Matières Littéraires', m: 'Moyenne 1' }, { t: 'Matières Scientifiques', s: 'Sous total Matières Scientifiques', m: 'Moyenne 2' }, { t: 'Matières Complémentaires', s: 'Sous total Matières Complémentaires', m: 'Moyenne 3' }];

const num = v => { const n = parseFloat(String(v).replace(',', '.')); return !isNaN(n) && n >= 0 && n <= 20 ? n : null; };
const f = (n, d = 1) => n == null || isNaN(n) ? '' : n.toFixed(d).replace('.', ',');
const fe = x => f(x, x < 9 ? 2 : 1);
const rg = r => r ? (r === 1 ? '1er' : r + 'e') : '';
const rangDans = (v, liste) => (v != null && Array.isArray(liste)) ? 1 + liste.filter(m => m > v + 1e-9).length : null;
const competence = m => m == null ? '' : m < CFG.seuilsCompetences[0] ? 'Non acquises' : m < CFG.seuilsCompetences[1] ? 'A acquérir' : m < CFG.seuilsCompetences[2] ? 'En cours d’acquisition' : 'Acquises';
const decision = m => m >= CFG.decision.passe ? 'Passe en classe supérieure' : m >= CFG.decision.conditionnel ? 'Redouble si échec' : 'Redouble';

/* ---------- calculs ---------- */
function calculer(o) {
  const seqs = o.seqs || {}, MAT = L.notesDe(o.classe).map(([m, c]) => [m, L.coef(o.notes, m, c)]);
  const groupes = GR.map(g => Object.assign({ rows: [] }, g));
  MAT.forEach(([m, c]) => {
    const t = TAB.find(x => x[0] === m), g = groupes[t ? t[2] : 2], lib = t ? t[1] : m;
    const nt = (seqs[m] || []).slice(0, 6).concat([null, null, null, null, null, null]).slice(0, 6).map(num);
    const vus = nt.filter(x => x != null); let note = num(o.notes[m]); if (note == null && vus.length) note = vus.reduce((a, b) => a + b, 0) / vus.length;
    g.rows.push({ key: m, n: lib, c, nt, note, ord: t ? TAB.indexOf(t) : 999, p: (o.profs || {})[m] || (o.profs || {})[lib] || ((o.cl && o.cl.profs) || {})[m] || (CFG.profs || {})[m] || (CFG.profs || {})[lib] || '' });
  });
  const ev = [0, 0, 0, 0, 0, 0], cn = [0, 0, 0, 0, 0, 0]; let mxc = 0, cs = 0;
  groupes.forEach(g => {
    g.rows.sort((a, b) => a.ord - b.ord);
    g.sub = [0, 0, 0, 0, 0, 0]; g.cn = [0, 0, 0, 0, 0, 0]; g.mxc = 0; g.cs = 0;
    g.rows.forEach(r => {
      r.nt.forEach((n, i) => { if (n != null) { g.sub[i] += n * r.c; g.cn[i] += r.c; } });
      if (r.note != null) { r.mxc = r.note * r.c; g.mxc += r.mxc; g.cs += r.c; }
    });
    g.moy = g.sub.map((x, i) => g.cn[i] ? x / g.cn[i] : null); g.moyAn = g.cs ? g.mxc / g.cs : null;
    g.sub.forEach((x, i) => { ev[i] += x; cn[i] += g.cn[i]; }); mxc += g.mxc; cs += g.cs;
  });
  const aSeq = cn.some(x => x > 0), evMoy = ev.map((x, i) => cn[i] ? x / cn[i] : null);
  const trim = [0, 2, 4].map(i => (cn[i] + cn[i + 1]) ? (ev[i] + ev[i + 1]) / (cn[i] + cn[i + 1]) : null);
  const moy = o.moyenne != null ? o.moyenne : (cs ? mxc / cs : null);
  return { groupes, ev, cn, evMoy, trim, mxc, cs, moy, aSeq };
}

/* ---------- mise en page (feuille de style limitée au bulletin) ---------- */
const CSS = '.bl{position:relative;width:794px;height:1160px;margin:0;background:#fff;color:#222;padding:14px 20px 10px;font:10px/1.2 Arial,Helvetica,sans-serif;overflow:hidden;box-sizing:border-box}.bl *{box-sizing:border-box}'
 + '.bl .b-h{display:flex;justify-content:space-between;align-items:flex-start}.bl .b-hb{width:232px;text-align:center;font-size:9.5px;font-weight:700;line-height:1.42;color:#333}.bl .b-hb i{font-size:9px}'
 + '.bl .b-lg{width:96px;height:80px;mix-blend-mode:multiply;margin-top:2px}.bl .b-bam{position:relative;height:20px;font-size:8px;text-align:center;padding-right:95px;color:#444}.bl .b-bam b{position:absolute;right:150px;top:2px;font-size:10px;font-weight:400}'
 + '.bl .b-ti{font-family:"Bookman Old Style",Georgia,"Times New Roman",serif;font-weight:900;text-align:center;font-size:16px;letter-spacing:3px;margin:2px 0 8px;color:#222}'
 + '.bl .b-inf{display:grid;grid-template-columns:156px 189px 46px 94px 59px 34px 87px 89px;line-height:17px;margin-bottom:3px;align-items:end}.bl .b-inf .b-k{font-weight:700;font-size:13px;color:#333}.bl .b-inf .b-s{font-style:italic;font-size:10px;color:#666}.bl .b-inf .b-n{font-style:italic;font-weight:700;font-size:14.5px;color:#222}.bl .b-inf .b-v{font-weight:700;font-size:13px;color:#222}'
 + '.bl table{border-collapse:collapse;width:100%;table-layout:fixed;background:none}.bl td,.bl th{border:1.2px solid #222;padding:0 2px;text-align:center;font-size:11px;overflow:hidden;white-space:nowrap;height:19px;color:#555;background:none}'
 + '.bl th{background:#d9d9d9;font-size:8.5px;white-space:normal;height:29px;color:#222;line-height:1.1}.bl td.b-l{text-align:left;font-size:11px;color:#333}.bl td.b-r{text-align:right;font-weight:700;border:0;padding-right:4px;font-size:10.5px;color:#222}.bl td.b-g{background:#d6d6d6;font-weight:700;color:#222}'
 + '.bl .b-sc{font-family:"Segoe Script","Brush Script MT",cursive;font-style:italic;font-weight:700;font-size:12px;white-space:normal;color:#222}.bl tr.b-sub td,.bl tr.b-moy td{font-weight:700;color:#111}.bl tr.b-sub td{border-top:2px solid #222;height:21px}'
 + '.bl .b-vt{writing-mode:vertical-rl;transform:rotate(180deg);font-weight:700;font-size:8.5px;background:#e4e4e4;padding:0;white-space:nowrap;color:#222}.bl .b-pf td{font-size:8.5px;font-weight:700;text-align:left;color:#222}'
 + '.bl .b-bt{position:relative;height:350px;margin-top:2px}.bl .b-bt>*{position:absolute;white-space:nowrap}.bl .b-u{text-decoration:underline;font-weight:700}.bl .b-hw{font-family:"Segoe Script","Palatino Linotype",Georgia,serif;font-style:italic;color:#222}'
 + '.bl .b-rd{color:#d0152a;font-family:"Segoe Script","Brush Script MT",cursive;font-style:italic;text-shadow:0 0 1px #d0152a}.bl .b-bx{border:1.3px solid #222;text-align:center;font-size:11px;background:#e6e6e6;height:20px;line-height:18px}'
 + '.bl .b-ib{font-style:italic;font-weight:700}.bl .b-lb{font-style:italic;font-size:11.5px;color:#333}.bl .b-lines{background:repeating-linear-gradient(#222 0 1px,transparent 1px 4px)}'
 + '.bl .b-pf td.b-r{text-align:right;font-size:9px}';
const STAMP = '<svg width="134" height="134" viewBox="0 0 134 134" style="mix-blend-mode:multiply;transform:rotate(-8deg)"><defs><path id="cpb" d="M67 67m-50 0a50 50 0 1 1 100 0a50 50 0 1 1-100 0"/></defs><g fill="none" stroke="#d0152a" stroke-width="2" opacity=".85"><circle cx="67" cy="67" r="64"/><circle cx="67" cy="67" r="42" stroke-width="1.2"/><circle cx="67" cy="67" r="58" stroke-width="1" stroke-dasharray="2 2"/></g><text font-size="9" font-weight="700" fill="#d0152a" opacity=".85" font-family="Arial"><textPath href="#cpb" startOffset="2">LYCEE DE BAHOUAN · GOVERNMENT HIGH SCHOOL · BAHOUAN ·</textPath></text><g fill="#d0152a" opacity=".85" font-family="Arial" font-size="8" font-weight="700" text-anchor="middle"><text x="67" y="58">LE PROVISEUR</text><text x="67" y="72" font-size="6.5">Décision du conseil</text></g><path d="M40 88c10-22 18 12 26-8s12 10 24-6" fill="none" stroke="#d0152a" stroke-width="1.8" opacity=".8"/></svg>';

/* ---------- le bulletin ---------- */
H.bulletin = o => {
  const R = calculer(o), cl = o.cl || {}, P = o.eleve || {}, moy = R.moy, abs = o.absences || [];
  const serie = L.serie(o.classe), classe = String(o.classe || '').replace(/^Première/i, '1ère').replace(/^Terminale/i, 'Tle');
  const annee = String(o.annee || '').replace(/\//g, '-');
  const nbAbs = abs.filter(x => /absent/i.test(x.statut)).length, nbSan = k => abs.filter(x => new RegExp(k, 'i').test(x.sanction || '')).length;
  const mc = Array.isArray(cl.moyennes) ? cl.moyennes : [], moyClasse = mc.length ? mc.reduce((a, b) => a + b, 0) / mc.length : null;
  const rEval = i => (o.seqRang && o.seqRang[i]) ? rg(o.seqRang[i]) : rg(rangDans(R.evMoy[i], cl.moySeq && cl.moySeq[i + 1])), rTrim = i => rg(rangDans(R.trim[i], cl.moyTrim && cl.moyTrim[i + 1]));
  const rAn = rg(o.rang || H.rang(moy, cl));
  const date = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' }).toUpperCase();
  const honneur = moy != null && moy >= H.SEUIL_HONNEUR;
  const t3 = R.trim[2] != null ? R.trim[2] : moy;
  let h = '<div class="bl" id="hn-bulletin"><style>' + CSS + '</style>';
  h += '<div class="b-h"><div class="b-hb">REPUBLIQUE DU CAMEROUN<br><i>Paix - Travail - Patrie</i><br>REGION DE L’OUEST<br>DELEGATION REGIONALE DES<br>ENSEIGNEMENTS SECONDAIRES<br>DELEGATION DEPARTEMENTALE DES<br>HAUTS PLATEAUX<br><span style="font-size:12px">LYCEE DE BAHOUAN</span><br>4HE1 GSFD 110 794 105</div>'
   + '<img class="b-lg" src="' + LOGO + '" alt="">'
   + '<div class="b-hb"><i>Peace -Work - Fatherland</i><br>WEST REGION<br>REGIONAL DELEGATION OF SECONDARY<br>EDUCATION<br>DIVISIONAL DELEGATION OF UPPER<br>PLATEAUX<br><span style="font-size:12px">GOVERNMENT HIGH SCHOOL<br>BAHOUAN</span><br>4HE1 GSFD 110 794 105</div></div>'
   + '<div class="b-bam">BAMENDJOU<b>Reg. Nr:</b></div><div class="b-ti">BULLETIN DE NOTES ANNUEL</div>'
   + '<div class="b-inf"><span class="b-k">Section:</span><span class="b-s">' + esc(CFG.section) + '</span><span class="b-s" style="grid-column:6/8;font-size:8.5px">Année Scolaire:</span><span class="b-v" style="font-size:14px">' + esc(annee) + '</span>'
   + '<span class="b-k">Spécialité:</span><span class="b-s">' + esc(CFG.specialites[serie] || '') + '</span><span class="b-k" style="grid-column:7">Classe:</span><span class="b-v" style="text-align:center">' + esc(classe) + '</span>'
   + '<span class="b-k">Nom de l’élève:</span><span class="b-n" style="grid-column:2/7">' + esc(o.nom) + '</span><span class="b-s" style="grid-column:7;font-size:9px">Redoublant:</span><span class="b-s" style="font-size:11px;color:#333">' + (moy != null && moy < 10 ? 'Oui' : 'Non') + '</span>'
   + '<span class="b-k">Date de Naissance:</span><span class="b-s" style="font-size:11px;color:#444">' + esc(P.naissance || '') + '</span><span class="b-k">Age:</span><span class="b-v" style="text-align:center">' + esc(P.age || '') + '</span><span class="b-k">Sexe:</span><span class="b-s" style="font-size:12px;color:#444">' + esc(P.sexe || '') + '</span><span class="b-k" style="grid-column:7">Matricule:</span><span style="font-size:11px;color:#444">' + esc(P.matricule || '') + '</span></div>';
  h += '<table><colgroup>' + [14, 168, 43, 43, 43, 43, 43, 43, 42, 36, 48, 70, 62, 46].map(w => '<col style="width:' + w + 'px">').join('') + '</colgroup>'
   + '<tr><th></th><th>MATIERES</th><th>Eval.1</th><th>Eval.2</th><th>Eval.3</th><th>Eval.4</th><th>Eval.5</th><th>Eval.6</th><th>Moy.<br>An./20</th><th>COEF</th><th>M X C</th><th>COMPETENCES</th><th>NOM DU PROF.</th><th>VISA DU PROF.</th></tr>';
  R.groupes.forEach((G, gi) => {
    if (!G.rows.length) return;
    const filler = gi === 2 ? 1 : 0;
    G.rows.forEach((r, i) => {
      h += '<tr>' + (i === 0 ? '<td class="b-vt" rowspan="' + (G.rows.length + 2 + filler) + '">' + G.t + '</td>' : '') + '<td class="b-l">' + esc(r.n) + '</td>' + r.nt.map(n => '<td>' + (n == null ? '' : f(n, n % 1 ? 1 : 0)) + '</td>').join('')
       + '<td class="b-g">' + f(r.note) + '</td><td>' + f(r.c) + '</td><td class="b-g">' + f(r.mxc) + '</td><td class="b-sc" style="font-weight:400;font-size:9.5px;white-space:nowrap;color:#444">' + competence(r.note) + '</td><td style="font-size:9px;font-style:italic;color:#333">' + esc(r.p) + '</td><td></td></tr>';
      if (filler && i === 0) h += '<tr><td class="b-l">---//---//---</td>' + '<td>0</td>'.repeat(6) + '<td class="b-g">0,0</td><td>0,0</td><td class="b-g">N.A/ABS</td><td class="b-sc" style="font-weight:400;font-size:9.5px;color:#444">-//-</td><td style="font-size:9px;font-style:italic">--//--</td><td></td></tr>';
    });
    h += '<tr class="b-sub"><td class="b-l">' + G.s + '</td>' + G.sub.map((x, i) => '<td>' + (G.cn[i] ? f(x) : '') + '</td>').join('') + '<td>' + f(G.mxc) + '</td><td>' + f(G.cs) + '</td><td>' + f(G.mxc) + '</td><td colspan="3" rowspan="2" class="b-sc" style="font-size:14px">' + competence(G.moyAn) + '</td></tr>'
     + '<tr class="b-moy"><td class="b-l">' + G.m + '</td>' + G.moy.map(x => '<td>' + f(x) + '</td>').join('') + '<td>' + f(G.moyAn) + '</td><td colspan="2">' + f(G.moyAn) + '</td></tr>';
  });
  h += '<tr><td colspan="2" class="b-r">Grand Total:</td>' + R.ev.map((x, i) => '<td><b>' + (R.cn[i] ? f(x) : '') + '</b></td>').join('') + '<td colspan="2"><b>' + f(R.cs, 0) + '</b></td><td><b>' + f(R.mxc) + '</b></td><td colspan="3" class="b-pf" style="text-align:center"><b style="font-size:9.5px">PROFIL ANNUEL DE LA CLASSE</b></td></tr>'
   + '<tr class="b-pf"><td colspan="2" class="b-r">Moyennes Devoirs/Evaluations:</td>' + R.evMoy.map(x => '<td style="font-size:11px;text-align:center">' + (x == null ? '' : fe(x)) + '</td>').join('') + '<td colspan="2">Moyenne Annuelle:</td><td style="font-size:11.5px">' + f(moy, 2) + '</td><td>Moyenne Classe</td><td colspan="2" style="text-align:center;font-size:11px">' + f(moyClasse, 3) + '</td></tr>'
   + '<tr class="b-pf"><td colspan="2" class="b-r">Rang par Dev/Eval:</td>' + [0, 1, 2, 3, 4, 5].map(i => '<td style="text-align:center;font-style:italic">' + rEval(i) + '</td>').join('') + '<td colspan="2">Rang annuel:</td><td style="text-align:center;font-size:11.5px">' + rAn + '</td><td>Effectif Total:</td><td colspan="2" style="text-align:center;font-size:11px">' + (cl.effectif || '') + '</td></tr>'
   + '<tr class="b-pf"><td colspan="2" class="b-r">Moyenne par Trimestre:</td>' + [0, 1, 2].map(i => '<td colspan="2" style="text-align:center;font-size:11.5px">' + f(R.trim[i], 2) + '</td>').join('') + '<td colspan="2">Moyenne 3e Trim.:</td><td style="text-align:center;font-size:11.5px">' + f(t3, 2) + '</td><td>Moyenne >=10</td><td colspan="2" style="text-align:center;font-size:11px">' + (mc.length ? mc.filter(m => m >= 10).length : '') + '</td></tr>'
   + '<tr class="b-pf"><td colspan="2" class="b-r">Rang par Trimestre:</td>' + [0, 1, 2].map(i => '<td colspan="2" style="text-align:center;font-size:11.5px">' + rTrim(i) + '</td>').join('') + '<td colspan="2">Rang 3e Trim.:</td><td style="text-align:center;font-size:11.5px">' + rTrim(2) + '</td><td>Moyenne Max:</td><td colspan="2" style="text-align:center;font-size:11px">' + (mc.length ? f(Math.max(...mc), 2) : '') + '</td></tr>'
   + '<tr class="b-pf"><td colspan="11" style="border:0;font-weight:400;font-size:8.5px;font-style:italic">N.B: Les coefficients appliqués ici pour l’année sont ceux de la Composition T3</td><td>Moyenne Min:</td><td colspan="2" style="text-align:center;font-size:11px">' + (mc.length ? f(Math.min(...mc), 2) : '') + '</td></tr></table>';
  const box = (x, y, w, v, st) => '<div class="b-bx" style="left:' + x + 'px;top:' + y + 'px;width:' + w + 'px;' + (st || '') + '">' + (v == null ? '' : v) + '</div>';
  const sceau = H.SIGNATURE_IMG ? '<img src="' + H.SIGNATURE_IMG + '" style="left:600px;top:130px;width:150px">' : '<div style="left:602px;top:124px;width:140px;height:140px">' + STAMP + '</div>';
  h += '<div class="b-bt">'
   + '<div class="b-u" style="left:215px;top:-2px;font-size:11.5px">Remarques générales du Chef d’établissement</div>'
   + '<div class="b-hw" style="left:136px;top:24px;font-size:' + ((H.mot(moy) || '').length > 60 ? 12.5 : 17.5) + 'px;font-weight:600">' + esc(moy == null ? '' : H.mot(moy)) + '</div>'
   + '<div class="b-rd" style="left:583px;top:-14px;font-size:21px;transform:rotate(-5deg)">' + (moy != null && decision(moy) === 'Redouble si échec' ? 'Redouble si échec' : '') + '</div>'
   + '<div class="b-u" style="left:586px;top:40px;font-size:9px">Appréciations du travail Annuel</div><div class="b-lines" style="left:586px;top:52px;width:190px;height:24px"></div>'
   + '<div style="left:640px;top:54px;background:#fff;padding:0 6px;font-family:\'Segoe Script\',\'Brush Script MT\',cursive;font-weight:900;font-style:italic;font-size:17px">' + (moy == null ? '' : (moy >= 20 ? 'Parfait' : L.mention(moy))) + '</div>'
   + '<div class="b-u" style="left:223px;top:49px;font-size:11.5px">CONDUITE DE L’ELEVE AU 3E TRIMESTRE</div>'
   + '<div class="b-lb" style="left:8px;top:82px;width:160px;text-align:right">Avertissements(O/N):</div>' + box(173, 79, 49, nbSan('avert') ? 'O' : 'N')
   + '<div class="b-lb" style="left:8px;top:102px;width:160px;text-align:right">Absences(Hrs):</div>' + box(173, 99, 49, nbAbs)
   + '<div class="b-lb" style="left:8px;top:122px;width:160px;text-align:right">Blâmes(O/N):</div>' + box(173, 119, 49, nbSan('bl[âa]me') ? 'O' : 'N')
   + '<div class="b-lb" style="left:226px;top:78px">Exclusions(Jours):</div><div class="b-lb" style="left:226px;top:99px">Suspensions(Fois):</div><div class="b-lb" style="left:226px;top:119px">Retards(Heures):</div>'
   + box(512, 61, 40, nbSan('exclusion')) + box(512, 81, 40, nbSan('suspension')) + box(512, 101, 40, 0)
   + '<div class="b-u" style="left:591px;top:80px;font-size:9.5px">Sanctions du conseil de classe</div><div style="left:628px;top:96px;font-size:9px;letter-spacing:1px;color:#444">-///////////////////-</div>'
   + '<div class="b-rd" style="left:662px;top:98px;font-size:10.5px;font-style:normal;font-family:Arial;font-weight:700;letter-spacing:1px;transform:rotate(-2deg)">' + esc(date) + '</div>'
   + '<div class="b-ib" style="left:517px;top:121px;font-size:9.5px">Motif du refus du T.H</div><div class="b-ib b-u" style="left:525px;top:136px;font-size:9.5px">Décision finale du conseil de classe</div>'
   + '<div style="left:0;top:148px;width:17px;height:17px;border:1.5px solid #222;text-align:center;font-weight:700">' + (honneur ? '✓' : '') + '</div>'
   + '<div class="b-ib" style="left:24px;top:150px;font-size:11.5px">“Oui” ou “Non” pour le Tableau d’Honneur</div><div class="b-u b-ib" style="left:96px;top:170px;font-size:11.5px">Appréciations générales de la discipline</div>'
   + '<table style="left:0;top:187px;width:437px;position:absolute"><colgroup><col style="width:43%"><col style="width:23%"><col style="width:11%"><col style="width:12%"><col style="width:11%"></colgroup><tr>'
   + ['Total Absences annuelles', 'Mauvaise', 'Moyenne', 'Bon', 'Très Bon'].map((x, i) => '<th style="' + (i ? '' : 'height:24px;') + 'font-style:italic;font-weight:400;color:#666">' + x + '</th>').join('')
   + '</tr><tr><td class="b-g" style="height:32px;font-size:13px">' + nbAbs + '</td><td class="b-g"></td><td class="b-g"></td><td class="b-g"></td><td class="b-g"></td></tr></table>'
   + '<div class="b-bx" style="left:422px;top:164px;width:188px;height:24px;color:#888;font-style:italic;letter-spacing:3px;line-height:22px">' + (moy != null && moy >= CFG.decision.conditionnel ? 'Promu' : '') + '</div>'
   + '<div class="b-ib" style="left:618px;top:155px;font-size:8px">Prochaine classe(promu)</div><div class="b-bx" style="left:746px;top:140px;width:40px;background:#fff"></div>'
   + '<div class="b-ib" style="left:423px;top:191px;font-size:9.5px">Motif du refus du rejet de la décision du conseil de classe:</div>'
   + '<div class="b-ib" style="left:427px;top:208px;font-size:9.5px;font-weight:400">Indiscipline...</div><div class="b-ib" style="left:523px;top:200px;font-size:9.5px;font-weight:400">Ne peut tripler</div>'
   + '<div class="b-ib" style="left:213px;top:249px;font-size:8px;color:#666;font-weight:400">Redouble en cas d’échec à l’examen?</div>'
   + '<div class="b-ib b-u" style="left:0;top:271px;font-size:11.5px">Signature du Professeur Principal:</div>'
   + box(173, 266, 53, 'Oui', 'height:24px;background:#fff;text-align:left;padding-left:4px;line-height:22px;color:#555') + box(276, 266, 69, 'Non.........', 'height:24px;background:#fff;text-align:left;padding-left:4px;line-height:22px;font-weight:700')
   + '<div style="left:322px;top:296px;font-size:8.5px;font-weight:700">Falcon Easy Students’ Assessments</div><div style="left:322px;top:309px;font-size:8.5px;font-weight:700">Editor: 651 52 84 16 / 677 86 83 86</div>'
   + (CFG.profPrincipal ? '<div style="left:0;top:294px;font-family:\'Segoe Script\',\'Brush Script MT\',cursive;font-style:italic;font-size:20px;color:#333">' + esc(CFG.profPrincipal) + '</div>' : '')
   + '<div style="left:6px;top:333px;font-size:9px;font-weight:700">▸ FalconSoft</div>' + sceau + '</div></div>';
  return h;
};
H.appreciation = n => n >= 20 ? 'Parfait' : L.mention(n);
})();
